  1→import { Injectable, ConflictException, NotFoundException } from '@nestjs/common';
  2→import { InjectRepository } from '@nestjs/typeorm';
  3→import { ConfigService } from '@nestjs/config';
  4→import { Repository } from 'typeorm';
  5→import { Vault } from './entities/vault.entity';
  6→import { PinnedCid } from './entities/pinned-cid.entity';
  7→import { FolderIpns } from '../ipns/entities/folder-ipns.entity';
  8→import { User } from '../auth/entities/user.entity';
  9→import { InitVaultDto, VaultResponseDto } from './dto/init-vault.dto';
 10→import { VaultExportDto } from './dto/vault-export.dto';
 11→import { QuotaResponseDto } from './dto/quota.dto';
 12→import { VaultConfigResponseDto } from './dto/vault-config.dto';
 13→import { TeeKeyStateService } from '../tee/tee-key-state.service';
 14→import { TeeKeysDto } from '../tee/dto/tee-keys.dto';
 15→
 16→/**
 17→ * Storage quota limit: 500 MiB
 18→ */
 19→export const QUOTA_LIMIT_BYTES = 500 * 1024 * 1024; // 524,288,000 bytes
 20→
 21→@Injectable()
 22→export class VaultService {
 23→  constructor(
 24→    @InjectRepository(Vault)
 25→    private readonly vaultRepository: Repository<Vault>,
 26→    @InjectRepository(PinnedCid)
 27→    private readonly pinnedCidRepository: Repository<PinnedCid>,
 28→    @InjectRepository(FolderIpns)
 29→    private readonly folderIpnsRepository: Repository<FolderIpns>,
 30→    @InjectRepository(User)
 31→    private readonly userRepository: Repository<User>,
 32→    private readonly teeKeyStateService: TeeKeyStateService,
 33→    private readonly configService: ConfigService
 34→  ) {}
 35→
 36→  /**
 37→   * Get application configuration including recycle bin retention period.
 38→   */
 39→  getConfig(): VaultConfigResponseDto {
 40→    const raw = this.configService.get<string>('RECYCLE_BIN_RETENTION_DAYS');
 41→    let retentionDays = Number(raw);
 42→    if (!Number.isFinite(retentionDays) || retentionDays < 0) {
 43→      retentionDays = 30;
 44→    }
 45→    return {
 46→      recycleBinRetentionDays: retentionDays,
 47→    };
 48→  }
 49→
 50→  /**
 51→   * Initialize a new vault for a user
 52→   * Creates the vault with encrypted keys on first sign-in
 53→   *
 54→   * @throws ConflictException if vault already exists for user
 55→   */
 56→  async initializeVault(userId: string, dto: InitVaultDto): Promise<VaultResponseDto> {
 57→    // Check if vault already exists
 58→    const existingVault = await this.vaultRepository.findOne({
 59→      where: { ownerId: userId },
 60→    });
 61→
 62→    if (existingVault) {
 63→      throw new ConflictException('Vault already exists for this user');
 64→    }
 65→
 66→    // Decode hex strings to buffers
 67→    const vault = this.vaultRepository.create({
 68→      ownerId: userId,
 69→      ownerPublicKey: Buffer.from(dto.ownerPublicKey, 'hex'),
 70→      rootIpnsName: dto.rootIpnsName,
 71→      initializedAt: null,
 72→    });
 73→
 74→    const savedVault = await this.vaultRepository.save(vault);
 75→
 76→    // Ensure root folder IPNS entry exists for publish tracking.
 77→    // The IPNS publish endpoint may have already created this row (clients
 78→    // publish the root folder IPNS record before calling /vault/init).
 79→    // Try insert first; on duplicate key, update isRoot instead.
 80→    try {
 81→      const rootFolderIpns = this.folderIpnsRepository.create({
 82→        userId,
 83→        ipnsName: dto.rootIpnsName,
 84→        latestCid: null,
 85→        sequenceNumber: '0',
 86→        encryptedIpnsPrivateKey: null,
 87→        keyEpoch: null,
 88→        isRoot: true,
 89→      });
 90→      await this.folderIpnsRepository.save(rootFolderIpns);
 91→    } catch (error) {
 92→      // Row already exists (from IPNS publish endpoint) — mark as root
 93→      if ((error as { code?: string }).code === '23505') {
 94→        await this.folderIpnsRepository.update(
 95→          { userId, ipnsName: dto.rootIpnsName },
 96→          { isRoot: true }
 97→        );
 98→      } else {
 99→        throw error;
100→      }
101→    }
102→
103→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
104→    return this.toVaultResponse(savedVault, teeKeys);
105→  }
106→
107→  /**
108→   * Get vault for a user
109→   *
110→   * @throws NotFoundException if vault does not exist
111→   */
112→  async getVault(userId: string): Promise<VaultResponseDto> {
113→    const vault = await this.vaultRepository.findOne({
114→      where: { ownerId: userId },
115→    });
116→
117→    if (!vault) {
118→      throw new NotFoundException('Vault not found');
119→    }
120→
121→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
122→    return this.toVaultResponse(vault, teeKeys);
123→  }
124→
125→  /**
126→   * Check if vault exists for user (returns null if not)
127→   */
128→  async findVault(userId: string): Promise<VaultResponseDto | null> {
129→    const vault = await this.vaultRepository.findOne({
130→      where: { ownerId: userId },
131→    });
132→
133→    if (!vault) return null;
134→
135→    const teeKeys = await this.teeKeyStateService.getTeeKeysDto();
136→    return this.toVaultResponse(vault, teeKeys);
137→  }
138→
139→  /**
140→   * Check if user is in BYO (Bring Your Own) IPFS mode.
141→   * BYO users manage their own IPFS node; quota is advisory only.
142→   */
143→  async isUserByo(userId: string): Promise<boolean> {
144→    const vault = await this.vaultRepository.findOne({
145→      where: { ownerId: userId },
146→      select: ['isByoUser'],
147→    });
148→    return vault?.isByoUser ?? false;
149→  }
150→
151→  /**
152→   * Set BYO status for a user's vault.
153→   */
154→  async setByoStatus(userId: string, isByo: boolean): Promise<void> {
155→    await this.vaultRepository.update({ ownerId: userId }, { isByoUser: isByo });
156→  }
157→
158→  /**
159→   * Get current storage quota usage for a user.
160→   * For BYO users, the advisory flag is set to true.
161→   */
162→  async getQuota(userId: string): Promise<QuotaResponseDto> {
163→    const isByo = await this.isUserByo(userId);
164→
165→    const result = await this.pinnedCidRepository
166→      .createQueryBuilder('pin')
167→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
168→      .where('pin.user_id = :userId', { userId })
169→      .getRawOne<{ total: string }>();
170→
171→    const usedBytes = parseInt(result?.total ?? '0', 10);
172→    const remainingBytes = Math.max(0, QUOTA_LIMIT_BYTES - usedBytes);
173→
174→    return {
175→      usedBytes,
176→      limitBytes: QUOTA_LIMIT_BYTES,
177→      remainingBytes,
178→      advisory: isByo,
179→    };
180→  }
181→
182→  /**
183→   * Check if user has sufficient quota for additional storage.
184→   * BYO users always pass (advisory only -- no enforcement).
185→   *
186→   * @returns true if BYO user OR (current usage + additionalBytes) <= quota limit
187→   */
188→  async checkQuota(userId: string, additionalBytes: number): Promise<boolean> {
189→    const isByo = await this.isUserByo(userId);
190→    if (isByo) return true; // Advisory only -- always allow
191→
192→    // Query usage directly to avoid redundant isUserByo call in getQuota
193→    const result = await this.pinnedCidRepository
194→      .createQueryBuilder('pin')
195→      .select('COALESCE(SUM(pin.size_bytes), 0)', 'total')
196→      .where('pin.user_id = :userId', { userId })
197→      .getRawOne<{ total: string }>();
198→
199→    const usedBytes = parseInt(result?.total ?? '0', 10);
200→    return usedBytes + additionalBytes <= QUOTA_LIMIT_BYTES;
201→  }
202→
203→  /**
204→   * Record a pinned CID for quota tracking
205→   * Uses upsert (ON CONFLICT DO NOTHING) for idempotency
206→   */
207→  async recordPin(userId: string, cid: string, sizeBytes: number): Promise<void> {
208→    await this.pinnedCidRepository
209→      .createQueryBuilder()
210→      .insert()
211→      .into(PinnedCid)
212→      .values({
213→        userId,
214→        cid,
215→        sizeBytes: sizeBytes.toString(),
216→      })
217→      .orIgnore() // ON CONFLICT DO NOTHING for idempotency
218→      .execute();
219→  }
220→
221→  /**
222→   * Remove a pinned CID record
223→   * Idempotent - no error if CID not found
224→   */
225→  async recordUnpin(userId: string, cid: string): Promise<void> {
226→    await this.pinnedCidRepository.delete({
227→      userId,
228→      cid,
229→    });
230→  }
231→
232→  /**
233→   * Mark vault as initialized (first file uploaded)
234→   */
235→  async markInitialized(userId: string): Promise<void> {
236→    await this.vaultRepository.update({ ownerId: userId }, { initializedAt: new Date() });
237→  }
238→
239→  /**
240→   * Get export data for independent recovery.
241→   * Returns the minimal set of fields needed to reconstruct the vault:
242→   * root IPNS name + encrypted root keys + derivation hints.
243→   */
244→  async getExportData(userId: string): Promise<VaultExportDto> {
245→    const vault = await this.vaultRepository.findOne({
246→      where: { ownerId: userId },
247→    });
248→
249→    if (!vault) {
250→      throw new NotFoundException('Vault not found');
251→    }
252→
253→    const user = await this.userRepository.findOne({
254→      where: { id: userId },
255→    });
256→
257→    return {
258→      format: 'cipherbox-vault-export',
259→      version: '1.0',
260→      exportedAt: new Date().toISOString(),
261→      rootIpnsName: vault.rootIpnsName,
262→      derivationMethod: user ? 'web3auth' : null,
263→    };
264→  }
265→
266→  /**
267→   * Convert Vault entity to response DTO with hex-encoded fields
268→   */
269→  private toVaultResponse(vault: Vault, teeKeys: TeeKeysDto | null = null): VaultResponseDto {
270→    return {
271→      id: vault.id,
272→      ownerPublicKey: vault.ownerPublicKey.toString('hex'),
273→      rootIpnsName: vault.rootIpnsName,
274→      createdAt: vault.createdAt,
275→      initializedAt: vault.initializedAt,
276→      teeKeys,
277→    };
278→  }
279→}
