  1→import { create } from 'zustand';
  2→import type { FolderChild } from '@cipherbox/core';
  3→import type { CipherBoxClient } from '@cipherbox/sdk';
  4→
  5→/**
  6→ * A folder node in the in-memory folder tree.
  7→ * Contains decrypted folder data and navigation state.
  8→ */
  9→export type FolderNode = {
 10→  /** UUID for internal reference (null string 'root' for root folder) */
 11→  id: string;
 12→  /** Folder name */
 13→  name: string;
 14→  /** IPNS name for this folder (k51.../bafzaa... format) */
 15→  ipnsName: string;
 16→  /** Parent folder ID (null for root) */
 17→  parentId: string | null;
 18→  /** Decrypted children (files and subfolders) */
 19→  children: FolderChild[];
 20→  /** Has metadata been fetched and decrypted? */
 21→  isLoaded: boolean;
 22→  /** Is metadata currently being fetched? */
 23→  isLoading: boolean;
 24→  /** Current IPNS sequence number */
 25→  sequenceNumber: bigint;
 26→  /** Decrypted AES-256 folder key */
 27→  folderKey: Uint8Array;
 28→  /** Decrypted Ed25519 IPNS private key */
 29→  ipnsPrivateKey: Uint8Array;
 30→};
 31→
 32→/**
 33→ * Breadcrumb entry for navigation.
 34→ */
 35→type Breadcrumb = {
 36→  id: string;
 37→  name: string;
 38→};
 39→
 40→type FolderState = {
 41→  // Folder tree indexed by id
 42→  folders: Record<string, FolderNode>;
 43→
 44→  // Current navigation
 45→  currentFolderId: string | null; // null = root
 46→  breadcrumbs: Breadcrumb[];
 47→
 48→  // Publishing state
 49→  pendingPublishes: Set<string>; // folder IDs with pending IPNS publishes
 50→
 51→  // Actions
 52→  setFolder: (folder: FolderNode) => void;
 53→  updateFolderChildren: (folderId: string, children: FolderChild[]) => void;
 54→  updateFolderSequence: (folderId: string, sequenceNumber: bigint) => void;
 55→  setCurrentFolder: (folderId: string | null) => void;
 56→  setBreadcrumbs: (breadcrumbs: Breadcrumb[]) => void;
 57→  addPendingPublish: (folderId: string) => void;
 58→  removePendingPublish: (folderId: string) => void;
 59→  removeFolder: (folderId: string) => void;
 60→  updateFolderName: (folderId: string, newName: string) => void;
 61→  clearFolders: () => void;
 62→
 63→  // SDK event subscription
 64→  subscribeToSdk: (client: CipherBoxClient) => void;
 65→};
 66→
 67→// Module-level unsubscribe callback — not part of Zustand state to avoid spurious re-renders
 68→let _folderSdkUnsubscribe: (() => void) | null = null;
 69→
 70→/**
 71→ * Folder store for managing folder tree state.
 72→ *
 73→ * Maintains the in-memory representation of the folder hierarchy
 74→ * with decrypted folder keys and metadata.
 75→ *
 76→ * SECURITY: All folder keys are memory-only - never persisted to storage.
 77→ * Call clearFolders() on logout to zero-fill all key material.
 78→ */
 79→export const useFolderStore = create<FolderState>((set, get) => ({
 80→  // State
 81→  folders: {},
 82→  currentFolderId: null,
 83→  breadcrumbs: [],
 84→  pendingPublishes: new Set<string>(),
 85→
 86→  // Actions
 87→  setFolder: (folder) =>
 88→    set((state) => ({
 89→      folders: { ...state.folders, [folder.id]: folder },
 90→    })),
 91→
 92→  updateFolderChildren: (folderId, children) =>
 93→    set((state) => {
 94→      const folder = state.folders[folderId];
 95→      if (!folder) return state;
 96→
 97→      return {
 98→        folders: {
 99→          ...state.folders,
100→          [folderId]: { ...folder, children, isLoaded: true, isLoading: false },
101→        },
102→      };
103→    }),
104→
105→  updateFolderSequence: (folderId, sequenceNumber) =>
106→    set((state) => {
107→      const folder = state.folders[folderId];
108→      if (!folder) return state;
109→
110→      return {
111→        folders: {
112→          ...state.folders,
113→          [folderId]: { ...folder, sequenceNumber },
114→        },
115→      };
116→    }),
117→
118→  setCurrentFolder: (folderId) => set({ currentFolderId: folderId }),
119→
120→  setBreadcrumbs: (breadcrumbs) => set({ breadcrumbs }),
121→
122→  addPendingPublish: (folderId) =>
123→    set((state) => {
124→      const newPending = new Set(state.pendingPublishes);
125→      newPending.add(folderId);
126→      return { pendingPublishes: newPending };
127→    }),
128→
129→  removePendingPublish: (folderId) =>
130→    set((state) => {
131→      const newPending = new Set(state.pendingPublishes);
132→      newPending.delete(folderId);
133→      return { pendingPublishes: newPending };
134→    }),
135→
136→  // Remove a folder from local state (after deletion)
137→  // Also clears the folder's key material from memory
138→  removeFolder: (folderId) =>
139→    set((state) => {
140→      const folder = state.folders[folderId];
141→      if (!folder) return state;
142→
143→      // Zero-fill keys before removing
144→      if (folder.folderKey) folder.folderKey.fill(0);
145→      if (folder.ipnsPrivateKey) folder.ipnsPrivateKey.fill(0);
146→
147→      const { [folderId]: _removed, ...remainingFolders } = state.folders;
148→      void _removed; // Intentionally destructured to remove from object
149→      return { folders: remainingFolders };
150→    }),
151→
152→  // Update a folder's name in local state
153→  updateFolderName: (folderId, newName) =>
154→    set((state) => {
155→      const folder = state.folders[folderId];
156→      if (!folder) return state;
157→
158→      return {
159→        folders: {
160→          ...state.folders,
161→          [folderId]: { ...folder, name: newName },
162→        },
163→      };
164→    }),
165→
166→  // [SECURITY: MEDIUM-02] Zero-fill sensitive key material before clearing
167→  clearFolders: () => {
168→    const state = get();
169→
170→    // Unsubscribe from SDK events before clearing
171→    if (_folderSdkUnsubscribe) {
172→      _folderSdkUnsubscribe();
173→      _folderSdkUnsubscribe = null;
174→    }
175→
176→    // Best-effort memory clearing - overwrite all folder keys with zeros
177→    for (const folder of Object.values(state.folders)) {
178→      if (folder.folderKey) {
179→        folder.folderKey.fill(0);
180→      }
181→      if (folder.ipnsPrivateKey) {
182→        folder.ipnsPrivateKey.fill(0);
183→      }
184→    }
185→
186→    set({
187→      folders: {},
188→      currentFolderId: null,
189→      breadcrumbs: [],
190→      pendingPublishes: new Set<string>(),
191→    });
192→  },
193→
194→  /**
195→   * Subscribe to SDK folder events. Called after SDK client is initialized.
196→   *
197→   * Maps SDK events (keyed by ipnsName) to store updates (keyed by folder id).
198→   * The SDK emits folderId = ipnsName, so we reverse-lookup to find the store's folder id.
199→   */
200→  subscribeToSdk: (client: CipherBoxClient) => {
201→    // Unsubscribe any existing subscription
202→    if (_folderSdkUnsubscribe) {
203→      _folderSdkUnsubscribe();
204→    }
205→
206→    _folderSdkUnsubscribe = client.on((event) => {
207→      switch (event.type) {
208→        case 'folder:loaded':
209→        case 'folder:updated': {
210→          // SDK uses ipnsName as folderId; find the matching store entry
211→          const folders = get().folders;
212→          const matchingFolder = Object.values(folders).find((f) => f.ipnsName === event.ipnsName);
213→          if (matchingFolder) {
214→            get().updateFolderChildren(matchingFolder.id, event.children);
215→            get().updateFolderSequence(matchingFolder.id, event.sequenceNumber);
216→          }
217→          break;
218→        }
219→        case 'folder:deleted': {
220→          // SDK uses ipnsName as folderId
221→          const folders = get().folders;
222→          const matchingFolder = Object.values(folders).find((f) => f.ipnsName === event.folderId);
223→          if (matchingFolder) {
224→            get().removeFolder(matchingFolder.id);
225→          }
226→          break;
227→        }
228→      }
229→    });
