 99→        .manage(app_state)
100→        .setup(|app| {
101→            // Hide dock icon -- menu bar only (pure background utility)
102→            #[cfg(target_os = "macos")]
103→            app.set_activation_policy(tauri::ActivationPolicy::Accessory);
