13→/// Handle completed Web3Auth authentication from the webview.
14→///
15→/// Called after the webview has completed the Web3Auth SDK flow and obtained
16→/// an idToken and the user's secp256k1 private key. This command:
17→/// 1. Sends idToken to backend to get access + refresh tokens
18→/// 2. Stores refresh token in macOS Keychain
19→/// 3. Stores private key and derived public key in AppState (memory only)
20→/// 4. Fetches and decrypts vault keys (including root IPNS keypair)
21→#[tauri::command]
22→pub async fn handle_auth_complete(
23→    app: tauri::AppHandle,
24→    state: State<'_, AppState>,
25→    id_token: String,
26→    private_key: String,
27→) -> Result<(), String> {
28→    log::info!("Handling auth completion from webview");
29→
30→    // Update tray status: Mounting (auth in progress, about to mount)
31→    let _ = crate::tray::update_tray_status(&app, &crate::tray::TrayStatus::Mounting);
32→
33→    // 1. Convert private key from hex to bytes and derive public key
34→    //    (needed for the login request)
35→    let private_key_hex = if private_key.starts_with("0x") {
36→        &private_key[2..]
37→    } else {
38→        &private_key
39→    };
40→    let private_key_bytes =
41→        hex::decode(private_key_hex).map_err(|_| "Invalid private key hex".to_string())?;
42→    if private_key_bytes.len() != 32 {
43→        return Err("Private key must be 32 bytes".to_string());
44→    }
45→
46→    // Derive uncompressed public key from private key (65 bytes, 0x04 prefix)
47→    // Used for both ECIES operations and backend auth (backend expects uncompressed)
48→    let public_key_bytes = derive_public_key(&private_key_bytes)?;
49→    let public_key_hex = hex::encode(&public_key_bytes); // 130 hex chars
50→
51→    // 2. Login with backend (requires uncompressed publicKey, 130 hex chars)
52→    let login_req = cipherbox_api_client::LoginRequest {
53→        id_token: id_token.clone(),
54→        public_key: public_key_hex,
55→        login_type: "corekit".to_string(),
56→    };
57→
58→    let resp = state
59→        .sdk
60→        .api
61→        .post("/auth/login", &login_req)
62→        .await
63→        .map_err(|e| format!("Login request failed: {}", e))?;
64→
65→    if !resp.status().is_success() {
66→        let status = resp.status();
67→        let body = resp.text().await.unwrap_or_default();
68→        return Err(format!("Login failed ({}): {}", status, body));
69→    }
70→
71→    let login_resp: cipherbox_api_client::LoginResponse = resp
72→        .json()
73→        .await
74→        .map_err(|e| format!("Failed to parse login response: {}", e))?;
75→
76→    // Delegate to shared post-auth setup
77→    complete_auth_setup(
78→        &app,
79→        &state,
