  1→/**
  2→ * @cipherbox/sdk - Event system
  3→ *
  4→ * Typed event definitions and a simple emitter for SDK state changes.
  5→ * Consumers subscribe to events to sync external state (e.g., Zustand stores)
  6→ * with SDK-internal state changes.
  7→ *
  8→ * Design: No external dependencies. The emitter is synchronous and
  9→ * subscriber errors are caught to prevent cascading failures.
 10→ */
 11→
 12→import type { FolderChild } from '@cipherbox/core';
 13→import type { BinEntry } from '@cipherbox/core';
 14→
 15→/**
 16→ * Union of all events emitted by the SDK.
 17→ *
 18→ * Events follow the pattern `domain:action` for easy filtering
 19→ * by consumers who only care about specific domains.
 20→ */
 21→export type SdkEvent =
 22→  | {
 23→      type: 'folder:loaded';
 24→      folderId: string;
 25→      ipnsName: string;
 26→      children: FolderChild[];
 27→      sequenceNumber: bigint;
 28→    }
 29→  | {
 30→      type: 'folder:updated';
 31→      folderId: string;
 32→      ipnsName: string;
 33→      children: FolderChild[];
 34→      sequenceNumber: bigint;
 35→    }
 36→  | { type: 'folder:deleted'; folderId: string }
 37→  | { type: 'file:uploaded'; folderId: string; fileName: string; cid: string }
 38→  | { type: 'file:downloaded'; cid: string }
 39→  | { type: 'bin:updated'; entries: BinEntry[] }
 40→  | { type: 'share:reWrapFailed'; folderIpnsName: string; failedRecipients: string[] }
 41→  | { type: 'pin:secondaryFailed'; cid: string; providerName: string; error: string }
 42→  | { type: 'ipns:batchPublishFailed'; ipnsNames: string[]; error: Error }
 43→  | { type: 'operation:start'; operation: string }
 44→  | { type: 'operation:end'; operation: string; durationMs: number }
 45→  | { type: 'error'; operation: string; error: Error };
 46→
 47→/**
 48→ * Handler function for SDK events.
 49→ * Consumers implement this to react to state changes.
 50→ */
 51→export type SdkEventHandler = (event: SdkEvent) => void;
 52→
 53→/**
 54→ * Simple typed event emitter. No external dependencies.
 55→ *
 56→ * Consumers subscribe with on() and unsubscribe with off() or the
 57→ * returned unsubscribe function. Handler errors are caught silently
 58→ * to prevent one subscriber from crashing the SDK or other subscribers.
 59→ */
 60→export class SdkEventEmitter {
 61→  private handlers: SdkEventHandler[] = [];
 62→
 63→  /**
 64→   * Subscribe to all SDK events.
 65→   * @returns An unsubscribe function for convenience
 66→   */
 67→  on(handler: SdkEventHandler): () => void {
 68→    this.handlers.push(handler);
 69→    return () => this.off(handler);
 70→  }
 71→
 72→  /**
 73→   * Unsubscribe a previously registered handler.
 74→   */
 75→  off(handler: SdkEventHandler): void {
 76→    this.handlers = this.handlers.filter((h) => h !== handler);
 77→  }
 78→
 79→  /**
 80→   * Emit an event to all subscribers.
 81→   * Handler errors are caught and swallowed -- subscriber bugs
 82→   * must not crash the SDK.
 83→   */
 84→  emit(event: SdkEvent): void {
 85→    for (const handler of this.handlers) {
 86→      try {
 87→        handler(event);
 88→      } catch {
 89→        /* subscriber errors don't crash SDK */
 90→      }
 91→    }
 92→  }
 93→
 94→  /**
 95→   * Remove all handlers. Called during client destroy().
 96→   */
 97→  removeAll(): void {
 98→    this.handlers = [];
 99→  }
100→}
