425→  try {
426→    const ciphertext = await encryptAesGcm(params.newContent, fileKey, iv);
427→
428→    // 2. Upload encrypted content to IPFS
429→    const { cid: contentCid } = await addToIpfs(params.ctx, new Uint8Array(ciphertext));
430→
431→    // 3. Wrap fileKey with owner's public key
432→    const ownerWrappedKey = await wrapKey(fileKey, params.ownerPublicKey);
433→    const fileKeyEncrypted = bytesToHex(ownerWrappedKey);
434→
435→    // 4. Get the file's IPNS private key
436→    const ipnsPrivKey = await params.getFileIpnsKeyFn(params.filePointer.id);
437→    if (!ipnsPrivKey) {
438→      throw new Error('Cannot update: no file IPNS key available');
439→    }
440→
441→    try {
442→      // 5. Resolve current file metadata
443→      const { metadata: currentMeta } = await resolveFileMetadata(
444→        params.filePointer.fileMetaIpnsName,
445→        params.folderKey,
446→        params.ctx
447→      );
448→
449→      // 6. Update file metadata
450→      const { ipnsRecord } = await updateFileMetadata({
451→        fileIpnsPrivateKey: ipnsPrivKey,
452→        fileMetaIpnsName: params.filePointer.fileMetaIpnsName,
453→        folderKey: params.folderKey,
454→        currentMetadata: currentMeta,
455→        updates: {
