    (k) => k.keyType === 'file-ipns' && k.itemId === itemId
  );
  const ipnsKeyRecord =
    exactMatch ??
    (shareItem.share.itemType === 'file'
      ? keys.find((k) => k.keyType === 'file-ipns')
      : undefined);

